        int warp = tid >> 5;
        for (int offset = 16; offset > 0; offset >>= 1) {
            sum += __shfl_down_sync(0xffffffff, sum, offset);
            sum_sq += __shfl_down_sync(0xffffffff, sum_sq, offset);
        }
        if (lane == 0) {
            reduction[warp] = sum;
            reduction_sq[warp] = sum_sq;
        }
        __syncthreads();
        if (warp == 0) {
            sum = (lane < 32) ? reduction[lane] : 0.0f;
            sum_sq = (lane < 32) ? reduction_sq[lane] : 0.0f;
            for (int offset = 16; offset > 0; offset >>= 1) {
                sum += __shfl_down_sync(0xffffffff, sum, offset);
                sum_sq += __shfl_down_sync(0xffffffff, sum_sq, offset);
            }
            if (lane == 0) {
                reduction[0] = sum;
                reduction_sq[0] = sum_sq;
            }
        }
        __syncthreads();
        float inv_cols = 1.0f / static_cast<float>(cols);
        float mean = reduction[0] * inv_cols;
        float variance = reduction_sq[0] * inv_cols - mean * mean;
        variance = fmaxf(variance, 0.0f);
        float inv_std = rsqrtf(variance + eps);
        if (use_vec4) {
            int64_t vec_cols = cols >> 2;
            float* row_y = y + row * cols;
            float4 const* x4 = reinterpret_cast<float4 const*>(row_x);
            float4* y4 = reinterpret_cast<float4*>(row_y);
            float4 const* w4 = reinterpret_cast<float4 const*>(weight);
            float4 const* b4 = reinterpret_cast<float4 const*>(bias);
            for (int64_t i = tid; i < vec_cols; i += blockDim.x) {
                float4 xv = x4[i];
                float4 wv = w4[i];
                float4 bv = b4[i];
                float4 out;
                out.x = (xv.x - mean) * inv_std * wv.x + bv.x;
                out.y = (xv.y - mean) * inv_std * wv.y + bv.y;
                out.z = (xv.z - mean) * inv_std * wv.z + bv.z;
                out.w = (xv.w - mean) * inv_std * wv.w + bv.w;
                y4[i] = out;
            }
        } else {
            float* row_y = y + row * cols;
            for (int64_t col = tid; col < cols; col += blockDim.x) {
                float normalized = (row_x[col] - mean) * inv_std;
                row_y[col] = normalized * weight[col] + bias[col];
            }
        }
    }
}


torch::Tensor cute_layer_norm(
    torch::Tensor x,
    torch::Tensor weight,
    torch::Tensor bias,
    double eps)
{
    TORCH_CHECK(x.is_cuda(), "x must be a CUDA tensor");
    TORCH_CHECK(weight.is_cuda() && bias.is_cuda(),
                "weight and bias must be CUDA tensors");
    TORCH_CHECK(x.scalar_type() == at::kFloat,
                "x must have dtype float32");
    TORCH_CHECK(weight.scalar_type() == at::kFloat &&
                bias.scalar_type() == at::kFloat,
                "weight and bias must have dtype float32");
    TORCH_CHECK(x.dim() >= 3, "x must have at least three dimensions");
    TORCH_CHECK(x.is_contiguous(), "x must be contiguous");
    TORCH_CHECK(weight.is_contiguous() && bias.is_contiguous(),
                "weight and bias must be contiguous");

    int64_t cols = x.size(x.dim() - 3) *
                   x.size(x.dim() - 2) *
                   x.size(x.dim() - 1);

    int64_t rows = x.numel() / cols;

    TORCH_CHECK(weight.numel() == cols,
                "weight must contain one value per normalized element");
    TORCH_CHECK(bias.numel() == cols,
                "bias must contain one value per normalized element");

    auto y = torch::empty_like(x);

    dim3 block(1024);
    int64_t grid_rows = rows > 0 ? (rows < 4096 ? rows : 4096) : 1;
    dim3 grid(static_cast<unsigned int>(grid_rows));

    cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();

    cute_layer_norm_kernel<<<grid, block, 0, stream>>>(
        x.data_ptr<float>(),
        weight.data_ptr<float>(),
        bias.data_ptr<float>(),
        y.data_ptr<float>(),
        rows,
        cols,
        static_cast<float>(eps));

    TORCH_CHECK(cudaGetLastError() == cudaSuccess,
                "CUTE layer normalization kernel launch failed");

    return y;
}
